@startuml

class Traveller {
  + Name : string
  + CompanyName : string
  + Address : string
  + BillingInformation : string
  + TravelPreferences : string[]
  + ReliabilityRating : float
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class RoomType {
  + Type : string
}

class Booking {
  + BookingIdentifier : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + MaxCostPerNight : float
  + CancellationDeadline : date
  + Status : string
}

class SpecialOffer {
  + Price : float
  + CityArea : string
  + HotelRating : int
  + Preferences : string[]
}

class CreditCardInfo {
  + CardNumber : string
  + ExpiryDate : date
}

class PaymentType {
  PrePaid
  PaidAtHotel
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinRating : int
  + MaxCostPerNight : float
  + Preferences : string[]
}

Hotel "0..*" -- "0..1" HotelChain
Hotel "0..*" -- "1" City
Hotel "1" -- "0..*" RoomType
Traveller "1" -- "0..*" Booking
Traveller "1" -- "0..*" SearchCriteria
Traveller "1" -- "1" CreditCardInfo
Booking "0..*" -- "1" Hotel
Booking "0..*" -- "1" PaymentType
Booking "1" -- "0..*" SpecialOffer
SpecialOffer "0..*" -- "1" Hotel
SpecialOffer "0..*" -- "1" Traveller

@enduml

